def _strict_abi_decode(types: list[str], raw: bytes) -> tuple[Any, ...]:
    values = abi_decode(types, raw)
    if abi_encode(types, values) != raw:
        raise ValueError("Non-canonical ABI output")
    return values


class DiesisPatronCampaignVoucherV1(TypedDict):
    campaign_id: bytes
    beneficiary: ChecksumAddress
    target: ChecksumAddress
    selector: bytes
    max_transactions: int
    max_lifetime_spend: int
    expiry: int
    nonce: int


class DiesisPatronGrantInfo(TypedDict):
    balance: int
    total_contributed: int
    total_spent: int


class DiesisPatronPendingReservationV2(TypedDict):
    grant_id: bytes
    beneficiary: ChecksumAddress
    maximum_fee: int


class DiesisPatronReservationExitSettlementV1(TypedDict):
    grant_id: bytes
    total_refund: int
    total_detached_shares: int
    remaining_detached_shares: int
    remaining_escrow: int


class DiesisPatronReservationExitSnapshotV1(TypedDict):
    detached_shares: int
    claimed: bool
    snapshotted: bool


class DiesisPatronContract:
    """Typed wrapper for the DiesisPatron contract."""

    def __init__(self, address: ChecksumAddress, w3: Web3) -> None:
        self.contract: Contract = w3.eth.contract(
            address=address, abi=DIESISPATRON_ABI,
        )

    # View/pure functions
    def accrued_burn(self) -> int:
        """Calls accruedBurn() through web3.py."""
        return self.contract.get_function_by_signature("accruedBurn()")().call()

    def campaign_id_for(self, owner: ChecksumAddress, salt: bytes) -> bytes:
        """Calls campaignIdFor(address,bytes32) through web3.py."""
        return self.contract.get_function_by_signature("campaignIdFor(address,bytes32)")(owner, salt).call()

    def campaign_owner(self, campaign_id: bytes) -> ChecksumAddress:
        """Calls campaignOwner(bytes32) through web3.py."""
        return self.contract.get_function_by_signature("campaignOwner(bytes32)")(campaign_id).call()

    def campaign_revoked(self, campaign_id: bytes) -> bool:
        """Calls campaignRevoked(bytes32) through web3.py."""
        return self.contract.get_function_by_signature("campaignRevoked(bytes32)")(campaign_id).call()

